Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:600;font-size:12px;">Multichannel convolution</div>

<label>C<sub>out</sub> (number of filters): <b id="cOutVal">2</b>
  <input id="cOutFilters" type="range" min="1" max="4" step="1" value="2">
</label>

<label>K (kernel size): <b id="kVal">3</b>
  <input id="kernelSize" type="range" min="1" max="5" step="1" value="3">
</label>

<button id="sweepWindow">▶ Slide the filter across x<sub>in</sub></button>
<button id="selectFilter">Isolate filter: none</button>

<div id="shapeOut" style="font-family:ui-monospace,Consolas,monospace;font-size:10.5px;line-height:1.5;"></div>

<div style="border-top:1px solid #dcdfe3;margin-top:4px;padding-top:4px;font-weight:600;font-size:12px;">Guided steps</div>
<div style="display:flex;gap:4px;">
  <button id="stepPrev" style="flex:1">◀ Prev</button>
  <button id="stepNext" style="flex:1">Next ▶</button>
</div>
<div id="stepTitle" style="font-weight:600;"></div>
<div id="stepNarr" style="font-size:11px;line-height:1.4;color:#333;"></div>

<div style="font-size:10px;color:#666;line-height:1.35;border-top:1px solid #dcdfe3;padding-top:4px;">
  Click a blue filter stack (or its pink output sheet) to isolate it. Drag the figure to ease the
  oblique shear out and see the true 3D stacks; “Figure view” restores the printed pose.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── element spec ───────────────────────────────────────────────────────────
// blue filter sheet   → PlaneGeometry(K*0.42, K*0.42) fill #cfe4f3 + LineSegments grid #000
// filter stack        → 3 sheets (C_in) at z = 0, -0.62, -1.24   (front sheet z = 0)
// pink input sheet    → PlaneGeometry(8*0.42, 8*0.42) fill #f7dcdc + LineSegments grid
// pink output sheet   → PlaneGeometry(N*0.42, N*0.42) fill #f7dcdc + grid, C_out sheets
// braces              → Line, two-quarter-arc curly brace, black
// patch highlight     → Line rect #d94f4f on each input sheet + blue fill plane on front sheet
// output cell marker  → Line rect #d94f4f on each output sheet
// accumulated cells   → InstancedMesh(PlaneGeometry(0.39,0.39)) #d94f4f @40%
// w / x_in / x_out / ⋆ / = / C_in / C_out / K / M / N → addLabel HTML (serif)
──────────────────────────────────────────────────────────────────────────── */

const CELL = 0.42;
const DZ   = 0.62;          // world depth per sheet → ~(0.22,0.22) screen under the shear
const CIN  = 3;
const M    = 8;
const BLUE = 0xcfe4f3, PINK = 0xf7dcdc, RED = 0xd94f4f, BLACK = 0x000000;

const AX = () => new THREE.Vector3(1, 0, 0);
const AY = () => new THREE.Vector3(0, 1, 0);
const AZ = () => new THREE.Vector3(0, 0, 1);

const root = new THREE.Group();
scene.add(root);

const state = { cOut: 2, K: 3, sel: -1, sweeping: false, idx: 0, filled: [] };

let filterStacks = [];   // [{group, cx, cy}]
let outSheets = [];      // [{group, inst, marker}]
let patchNodes = [];
let outMarkers = [];
let inputStack = null;
let firstBuild = true;

/* ── labels ──────────────────────────────────────────────────────────────── */
const myLabels = [];
const SER = s => `<span style="font-family:'Times New Roman',Times,serif">${s}</span>`;
function L(text, pos, opts) { const e = addLabel(text, pos, opts); myLabels.push(e); return e; }
function clearLabels() {
  while (myLabels.length) {
    const e = myLabels.pop();
    const i = _labels.indexOf(e);
    if (i >= 0) _labels.splice(i, 1);
    e.div.remove();
  }
}

/* ── geometry helpers ────────────────────────────────────────────────────── */
function gridLines(rows, cols, cell, z, color) {
  const w = cols * cell, h = rows * cell, pts = [];
  for (let i = 0; i <= cols; i++) { const x = -w / 2 + i * cell; pts.push(new THREE.Vector3(x, -h / 2, z), new THREE.Vector3(x, h / 2, z)); }
  for (let j = 0; j <= rows; j++) { const y = -h / 2 + j * cell; pts.push(new THREE.Vector3(-w / 2, y, z), new THREE.Vector3(w / 2, y, z)); }
  return new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color, transparent: true, opacity: 1 }));
}

function makeSheet(rows, cols, color) {
  const g = new THREE.Group();
  const w = cols * CELL, h = rows * CELL;
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1, side: THREE.DoubleSide }));
  g.add(fill);
  g.add(gridLines(rows, cols, CELL, 0.004, BLACK));
  g.userData.w = w; g.userData.h = h;
  return g;
}

function makeStack(rows, cols, color, n) {
  const g = new THREE.Group();
  for (let i = 0; i < n; i++) { const s = makeSheet(rows, cols, color); s.position.z = -i * DZ; g.add(s); }
  return g;
}

function rectLine(w, h, z, color) {
  const a = w / 2, b = h / 2;
  const pts = [[-a, -b], [a, -b], [a, b], [-a, b], [-a, -b]].map(p => new THREE.Vector3(p[0], p[1], z));
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color }));
}

function bracePoints(Lz, r) {
  r = Math.min(r, Lz / 4);
  const p = [], N = 10;
  for (let k = 0; k <= N; k++) { const t = Math.PI - (Math.PI / 2) * (k / N); p.push([-Lz / 2 + r + r * Math.cos(t), r * Math.sin(t)]); }
  for (let k = 0; k <= N; k++) { const t = -Math.PI / 2 + (Math.PI / 2) * (k / N); p.push([-r + r * Math.cos(t), 2 * r + r * Math.sin(t)]); }
  const q = p.slice();
  for (let k = p.length - 2; k >= 0; k--) q.push([-p[k][0], p[k][1]]);
  return q;
}

/** draws a curly brace; returns the world position of its middle tip */
function addBrace(center, axis, bulge, len, r = 0.13) {
  const a = axis.normalize(), b = bulge.normalize();
  const pts = bracePoints(Math.max(len, 0.3), r).map(([u, v]) =>
    center.clone().addScaledVector(a, u).addScaledVector(b, v));
  root.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: BLACK })));
  return center.clone().addScaledVector(b, 2 * Math.min(r, Math.max(len, 0.3) / 4));
}

function setOpacity(obj, o) {
  obj.traverse(n => {
    if (n.material) {
      const base = n.userData.baseOpacity !== undefined ? n.userData.baseOpacity : 1;
      n.material.transparent = true;
      n.material.opacity = o * base;
    }
  });
}

/* ── build ───────────────────────────────────────────────────────────────── */
function clearRoot() {
  while (root.children.length) { const c = root.children.pop(); _disposeObject(c); }
}

function build() {
  clearRoot(); clearLabels();
  filterStacks = []; outSheets = []; patchNodes = []; outMarkers = [];

  const K = state.K, C = state.cOut, N = M - K + 1;
  const fx = -6.2, inX = -1.0, outX = 4.6;
  const pitch = K * CELL + 0.7;
  const stackY = i => ((C - 1) / 2 - i) * pitch;
  const zMid = -(CIN - 1) * DZ / 2;

  /* filters */
  for (let i = 0; i < C; i++) {
    const st = makeStack(K, K, BLUE, CIN);
    st.position.set(fx, stackY(i), 0);
    root.add(st);
    filterStacks.push(st);
  }

  /* input */
  inputStack = makeStack(M, M, PINK, CIN);
  inputStack.position.set(inX, 0, 0);
  root.add(inputStack);

  /* receptive patch on every input sheet */
  for (let j = 0; j < CIN; j++) {
    const g = new THREE.Group();
    if (j === 0) {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(K * CELL, K * CELL),
        new THREE.MeshBasicMaterial({ color: BLUE, transparent: true, opacity: 0.95, side: THREE.DoubleSide }));
      m.position.z = 0.012; g.add(m);
      g.add(gridLines(K, K, CELL, 0.014, BLACK));
    }
    g.add(rectLine(K * CELL, K * CELL, 0.018, RED));
    g.position.z = -j * DZ;
    inputStack.add(g);
    patchNodes.push(g);
  }

  /* output: one sheet per filter */
  const outGroup = new THREE.Group();
  outGroup.position.set(outX, 0, 0);
  root.add(outGroup);
  for (let i = 0; i < C; i++) {
    const s = makeSheet(N, N, PINK);
    s.position.z = -i * DZ;
    const inst = new THREE.InstancedMesh(
      new THREE.PlaneGeometry(CELL * 0.94, CELL * 0.94),
      new THREE.MeshBasicMaterial({ color: RED, transparent: true, opacity: 0.4, side: THREE.DoubleSide }),
      Math.max(1, N * N));
    inst.userData.baseOpacity = 0.4;
    inst.frustumCulled = false;
    s.add(inst);
    const mk = rectLine(CELL, CELL, 0.02, RED);
    s.add(mk);
    outMarkers.push(mk);
    outGroup.add(s);
    outSheets.push({ group: s, inst });
  }

  /* ── braces ── */
  const topY = stackY(0) + K * CELL / 2, botY = stackY(C - 1) - K * CELL / 2;
  const fHalf = K * CELL / 2;

  // tall C_out filters brace
  let tip = addBrace(new THREE.Vector3(fx - fHalf - 0.45, (topY + botY) / 2, 0),
    AY(), AX().negate(), topY - botY, 0.16);
  L(SER(`<span style="display:inline-block;transform:rotate(-90deg)"><i>C</i><sub>out</sub> filters</span>`),
