  oblique shear out and see the true 3D stacks; “Figure view” restores the printed pose.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── element spec ───────────────────────────────────────────────────────────
// blue filter sheet   → PlaneGeometry(K*0.42, K*0.42) fill #cfe4f3 + LineSegments grid #000
// filter stack        → 3 sheets (C_in) at z = 0, -0.62, -1.24   (front sheet z = 0)
// pink input sheet    → PlaneGeometry(8*0.42, 8*0.42) fill #f7dcdc + LineSegments grid
// pink output sheet   → PlaneGeometry(N*0.42, N*0.42) fill #f7dcdc + grid, C_out sheets
// braces              → Line, two-quarter-arc curly brace, black
// patch highlight     → Line rect #d94f4f on each input sheet + blue fill plane on front sheet
// output cell marker  → Line rect #d94f4f on each output sheet
// accumulated cells   → InstancedMesh(PlaneGeometry(0.39,0.39)) #d94f4f @40%
// w / x_in / x_out / ⋆ / = / C_in / C_out / K / M / N → addLabel HTML (serif)
──────────────────────────────────────────────────────────────────────────── */

const CELL = 0.42;
const DZ   = 0.62;          // world depth per sheet → ~(0.22,0.22) screen under the shear
const CIN  = 3;
const M    = 8;
const BLUE = 0xcfe4f3, PINK = 0xf7dcdc, RED = 0xd94f4f, BLACK = 0x000000;

const AX = () => new THREE.Vector3(1, 0, 0);
const AY = () => new THREE.Vector3(0, 1, 0);
const AZ = () => new THREE.Vector3(0, 0, 1);

const root = new THREE.Group();
scene.add(root);

const state = { cOut: 2, K: 3, sel: -1, sweeping: false, idx: 0, filled: [] };

let filterStacks = [];   // [{group, cx, cy}]
let outSheets = [];      // [{group, inst, marker}]
let patchNodes = [];
let outMarkers = [];
let inputStack = null;
let firstBuild = true;

/* ── labels ──────────────────────────────────────────────────────────────── */
const myLabels = [];
const SER = s => `<span style="font-family:'Times New Roman',Times,serif">${s}</span>`;
function L(text, pos, opts) { const e = addLabel(text, pos, opts); myLabels.push(e); return e; }
function clearLabels() {
  while (myLabels.length) {
    const e = myLabels.pop();
    const i = _labels.indexOf(e);
    if (i >= 0) _labels.splice(i, 1);
    e.div.remove();
  }
}

/* ── geometry helpers ────────────────────────────────────────────────────── */
function gridLines(rows, cols, cell, z, color) {
  const w = cols * cell, h = rows * cell, pts = [];
  for (let i = 0; i <= cols; i++) { const x = -w / 2 + i * cell; pts.push(new THREE.Vector3(x, -h / 2, z), new THREE.Vector3(x, h / 2, z)); }
  for (let j = 0; j <= rows; j++) { const y = -h / 2 + j * cell; pts.push(new THREE.Vector3(-w / 2, y, z), new THREE.Vector3(w / 2, y, z)); }
  return new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color, transparent: true, opacity: 1 }));
}

function makeSheet(rows, cols, color) {
  const g = new THREE.Group();
  const w = cols * CELL, h = rows * CELL;
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1, side: THREE.DoubleSide }));
  g.add(fill);
  g.add(gridLines(rows, cols, CELL, 0.004, BLACK));
  g.userData.w = w; g.userData.h = h;
  return g;
}

function makeStack(rows, cols, color, n) {
  const g = new THREE.Group();
  for (let i = 0; i < n; i++) { const s = makeSheet(rows, cols, color); s.position.z = -i * DZ; g.add(s); }
  return g;
}

function rectLine(w, h, z, color) {
  const a = w / 2, b = h / 2;
  const pts = [[-a, -b], [a, -b], [a, b], [-a, b], [-a, -b]].map(p => new THREE.Vector3(p[0], p[1], z));
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color }));
}

function bracePoints(Lz, r) {
  r = Math.min(r, Lz / 4);
  const p = [], N = 10;
  for (let k = 0; k <= N; k++) { const t = Math.PI - (Math.PI / 2) * (k / N); p.push([-Lz / 2 + r + r * Math.cos(t), r * Math.sin(t)]); }
  for (let k = 0; k <= N; k++) { const t = -Math.PI / 2 + (Math.PI / 2) * (k / N); p.push([-r + r * Math.cos(t), 2 * r + r * Math.sin(t)]); }
  const q = p.slice();
  for (let k = p.length - 2; k >= 0; k--) q.push([-p[k][0], p[k][1]]);
  return q;
}

/** draws a curly brace; returns the world position of its middle tip */
function addBrace(center, axis, bulge, len, r = 0.13) {
  const a = axis.normalize(), b = bulge.normalize();
  const pts = bracePoints(Math.max(len, 0.3), r).map(([u, v]) =>
    center.clone().addScaledVector(a, u).addScaledVector(b, v));
  root.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: BLACK })));
  return center.clone().addScaledVector(b, 2 * Math.min(r, Math.max(len, 0.3) / 4));
}

function setOpacity(obj, o) {
  obj.traverse(n => {
    if (n.material) {
      const base = n.userData.baseOpacity !== undefined ? n.userData.baseOpacity : 1;
      n.material.transparent = true;
      n.material.opacity = o * base;
    }
  });
}

/* ── build ───────────────────────────────────────────────────────────────── */
function clearRoot() {
  while (root.children.length) { const c = root.children.pop(); _disposeObject(c); }
}

function build() {
  clearRoot(); clearLabels();
  filterStacks = []; outSheets = []; patchNodes = []; outMarkers = [];

  const K = state.K, C = state.cOut, N = M - K + 1;
  const fx = -6.2, inX = -1.0, outX = 4.6;
  const pitch = K * CELL + 0.7;
  const stackY = i => ((C - 1) / 2 - i) * pitch;
  const zMid = -(CIN - 1) * DZ / 2;

  /* filters */
  for (let i = 0; i < C; i++) {
    const st = makeStack(K, K, BLUE, CIN);
    st.position.set(fx, stackY(i), 0);
    root.add(st);
    filterStacks.push(st);
  }

  /* input */
  inputStack = makeStack(M, M, PINK, CIN);
  inputStack.position.set(inX, 0, 0);
  root.add(inputStack);

  /* receptive patch on every input sheet */
  for (let j = 0; j < CIN; j++) {
    const g = new THREE.Group();
    if (j === 0) {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(K * CELL, K * CELL),
        new THREE.MeshBasicMaterial({ color: BLUE, transparent: true, opacity: 0.95, side: THREE.DoubleSide }));
      m.position.z = 0.012; g.add(m);
      g.add(gridLines(K, K, CELL, 0.014, BLACK));
    }
    g.add(rectLine(K * CELL, K * CELL, 0.018, RED));
    g.position.z = -j * DZ;
    inputStack.add(g);
    patchNodes.push(g);
  }

  /* output: one sheet per filter */
  const outGroup = new THREE.Group();
  outGroup.position.set(outX, 0, 0);
  root.add(outGroup);
  for (let i = 0; i < C; i++) {
    const s = makeSheet(N, N, PINK);
    s.position.z = -i * DZ;
    const inst = new THREE.InstancedMesh(
      new THREE.PlaneGeometry(CELL * 0.94, CELL * 0.94),
      new THREE.MeshBasicMaterial({ color: RED, transparent: true, opacity: 0.4, side: THREE.DoubleSide }),
      Math.max(1, N * N));
    inst.userData.baseOpacity = 0.4;
    inst.frustumCulled = false;
    s.add(inst);
    const mk = rectLine(CELL, CELL, 0.02, RED);
    s.add(mk);
    outMarkers.push(mk);
    outGroup.add(s);
    outSheets.push({ group: s, inst });
  }

  /* ── braces ── */
  const topY = stackY(0) + K * CELL / 2, botY = stackY(C - 1) - K * CELL / 2;
  const fHalf = K * CELL / 2;

  // tall C_out filters brace
  let tip = addBrace(new THREE.Vector3(fx - fHalf - 0.45, (topY + botY) / 2, 0),
    AY(), AX().negate(), topY - botY, 0.16);
  L(SER(`<span style="display:inline-block;transform:rotate(-90deg)"><i>C</i><sub>out</sub> filters</span>`),
    tip.clone().add(new THREE.Vector3(-0.45, 0, 0)), { fontSize: '15px' });

  // C_in above top filter stack (along +Z)
  tip = addBrace(new THREE.Vector3(fx + 0.15, topY + 0.20, zMid), AZ(), AY(), (CIN - 1) * DZ, 0.11);
  L(SER('<i>C</i><sub>in</sub>'), tip.clone().add(new THREE.Vector3(0.18, 0.34, -0.30)), { fontSize: '16px' });

  // K on the right of the lowest filter stack
  tip = addBrace(new THREE.Vector3(fx + fHalf + 0.18, stackY(C - 1), 0), AY(), AX(), K * CELL, 0.12);
  L(SER('<i>K</i>'), tip.clone().add(new THREE.Vector3(0.32, 0, 0)), { fontSize: '16px' });

  // K under the lowest filter stack
  tip = addBrace(new THREE.Vector3(fx, stackY(C - 1) - fHalf - 0.18, 0), AX(), AY().negate(), K * CELL, 0.12);
  L(SER('<i>K</i>'), tip.clone().add(new THREE.Vector3(0, -0.32, 0)), { fontSize: '16px' });

  // C_in above input (along +Z)
  tip = addBrace(new THREE.Vector3(inX + 0.5, M * CELL / 2 + 0.20, zMid), AZ(), AY(), (CIN - 1) * DZ, 0.11);
  L(SER('<i>C</i><sub>in</sub>'), tip.clone().add(new THREE.Vector3(0.18, 0.34, -0.30)), { fontSize: '16px' });

  // M under input
  tip = addBrace(new THREE.Vector3(inX, -M * CELL / 2 - 0.18, 0), AX(), AY().negate(), M * CELL, 0.14);
  L(SER('<i>M</i>'), tip.clone().add(new THREE.Vector3(0, -0.34, 0)), { fontSize: '16px' });

  // C_out above output (along +Z)
  tip = addBrace(new THREE.Vector3(outX + 0.45, N * CELL / 2 + 0.20, -(C - 1) * DZ / 2),
    AZ(), AY(), Math.max((C - 1) * DZ, 0.45), 0.11);
  L(SER('<i>C</i><sub>out</sub>'), tip.clone().add(new THREE.Vector3(0.22, 0.34, -0.28)), { fontSize: '16px' });

  // N on the right of output
  tip = addBrace(new THREE.Vector3(outX + N * CELL / 2 + 0.18, 0, 0), AY(), AX(), N * CELL, 0.14);
  L(SER('<i>N</i>'), tip.clone().add(new THREE.Vector3(0.34, 0, 0)), { fontSize: '16px' });

  /* ── camera ── */
  if (firstBuild || !_userMovedCamera) {
    setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, heightFraction: 0.62 });
  }
  firstBuild = false;

  /* ── headline labels & operators ── */
  L(SER('<b>w</b>'), new THREE.Vector3(fx, topY + 0.58, zMid), { fontSize: '17px' });
  L(SER('<b>x</b><sub>in</sub>'), new THREE.Vector3(inX, M * CELL / 2 + 0.58, zMid), { fontSize: '17px' });
  L(SER('<b>x</b><sub>out</sub>'), new THREE.Vector3(outX, N * CELL / 2 + 0.58, -(C - 1) * DZ / 2), { fontSize: '17px' });
  L(SER('&#8902;'), new THREE.Vector3(-3.6, 0, 0), { fontSize: '26px' });
  L(SER('='), new THREE.Vector3(2.3, 0, 0), { fontSize: '26px' });

  /* ── state-dependent visuals ── */
  state.filled = new Array(N * N).fill(false);
  state.idx = 0;
  if (state.sel >= C) state.sel = -1;
  updatePatch(0, 0);
  updateFilled();
  applySelection();
  updateReadout();
}

/* ── highlight / accumulation ────────────────────────────────────────────── */
function updatePatch(row, col) {
  const K = state.K, N = M - K + 1;
  const px = -M * CELL / 2 + (col + K / 2) * CELL;
  const py = M * CELL / 2 - (row + K / 2) * CELL;
  patchNodes.forEach(g => { g.position.x = px; g.position.y = py; });
  const ox = -N * CELL / 2 + (col + 0.5) * CELL;
  const oy = N * CELL / 2 - (row + 0.5) * CELL;
  outMarkers.forEach(g => { g.position.x = ox; g.position.y = oy; });
}

const _mtx = new THREE.Matrix4();
function updateFilled() {
  const N = M - state.K + 1;
  for (const o of outSheets) {
    for (let p = 0; p < N * N; p++) {
      const r = Math.floor(p / N), c = p % N;
      const s = state.filled[p] ? 1 : 0.0001;
      _mtx.makeScale(s, s, 1);
      _mtx.setPosition(-N * CELL / 2 + (c + 0.5) * CELL, N * CELL / 2 - (r + 0.5) * CELL, 0.008);
      o.inst.setMatrixAt(p, _mtx);
    }
    o.inst.instanceMatrix.needsUpdate = true;
  }
}

function applySelection() {
  for (let i = 0; i < filterStacks.length; i++) {
    setOpacity(filterStacks[i], (state.sel < 0 || state.sel === i) ? 1 : 0.3);
  }
  for (let i = 0; i < outSheets.length; i++) {
    setOpacity(outSheets[i].group, (state.sel < 0 || state.sel === i) ? 1 : 0.3);
  }
  const b = document.getElementById('selectFilter');
  b.textContent = 'Isolate filter: ' + (state.sel < 0 ? 'none' : '#' + (state.sel + 1));
  b.classList.toggle('active', state.sel >= 0);
}

function updateReadout() {
  const K = state.K, C = state.cOut, N = M - K + 1;
  document.getElementById('shapeOut').innerHTML =
    `w    : ${C} × ${CIN} × ${K} × ${K}<br>` +
    `x_in : ${CIN} × ${M} × ${M}<br>` +
    `x_out: ${C} × ${N} × ${N}&nbsp;&nbsp;(N = M−K+1)`;
}

/* ── sweep animation ─────────────────────────────────────────────────────── */
let sweepTimer = null;
function sweepTick() {
  const N = M - state.K + 1;
  if (state.idx === 0) state.filled.fill(false);
  const p = state.idx;
  const r = Math.floor(p / N), c = p % N;
  updatePatch(r, c);
  state.filled[p] = true;
  updateFilled();
  state.idx = (p + 1) % (N * N);
}
function startSweep() {
  if (state.sweeping) return;
  state.sweeping = true;
  document.getElementById('sweepWindow').classList.add('active');
  document.getElementById('sweepWindow').innerHTML = '❚❚ Pause sweep';
  sweepTick();
  sweepTimer = setInterval(sweepTick, 250);
}
function stopSweep() {
  state.sweeping = false;
  clearInterval(sweepTimer); sweepTimer = null;
  document.getElementById('sweepWindow').classList.remove('active');
  document.getElementById('sweepWindow').innerHTML = '▶ Slide the filter across x<sub>in</sub>';
}

/* ── controls ────────────────────────────────────────────────────────────── */
const cOutInput = document.getElementById('cOutFilters');
const kInput = document.getElementById('kernelSize');

function syncInputs() {
  cOutInput.value = state.cOut; kInput.value = state.K;
  document.getElementById('cOutVal').textContent = state.cOut;
  document.getElementById('kVal').textContent = state.K;
}

cOutInput.addEventListener('input', () => {
  state.cOut = parseInt(cOutInput.value, 10);
  syncInputs(); build();
});
kInput.addEventListener('input', () => {
  state.K = parseInt(kInput.value, 10);
  syncInputs(); build();
});
document.getElementById('sweepWindow').addEventListener('click', () => {
  if (state.sweeping) { stopSweep(); state.idx = 0; state.filled.fill(false); updateFilled(); updatePatch(0, 0); }
  else startSweep();
});
document.getElementById('selectFilter').addEventListener('click', () => {
  state.sel = state.sel + 1 >= state.cOut ? -1 : state.sel + 1;
  applySelection();
});

/* ── screen-space picking (oblique shear makes raycasting unreliable) ────── */
function quadHit(ndc, center, ex, ey) {
  const c = center.clone().project(camera);
  const a = center.clone().add(ex).project(camera).sub(c);
  const b = center.clone().add(ey).project(camera).sub(c);
  const dx = ndc.x - c.x, dy = ndc.y - c.y;
  const det = a.x * b.y - a.y * b.x;
  if (Math.abs(det) < 1e-9) return false;
  const s = (dx * b.y - dy * b.x) / det, t = (a.x * dy - a.y * dx) / det;
  return Math.abs(s) <= 1 && Math.abs(t) <= 1;
}

function pick(ev) {
  const rect = canvas.getBoundingClientRect();
  const ndc = {
    x: ((ev.clientX - rect.left) / rect.width) * 2 - 1,
    y: -((ev.clientY - rect.top) / rect.height) * 2 + 1
  };
  const K = state.K, N = M - K + 1;
  for (let i = 0; i < filterStacks.length; i++) {
    const st = filterStacks[i];
    for (let j = 0; j < CIN; j++) {
      const c = new THREE.Vector3(st.position.x, st.position.y, -j * DZ);
      if (quadHit(ndc, c, new THREE.Vector3(K * CELL / 2, 0, 0), new THREE.Vector3(0, K * CELL / 2, 0)))
        return { kind: 'filter', i };
    }
  }
  for (let i = 0; i < outSheets.length; i++) {
    const c = new THREE.Vector3(4.6, 0, -i * DZ);
    if (quadHit(ndc, c, new THREE.Vector3(N * CELL / 2, 0, 0), new THREE.Vector3(0, N * CELL / 2, 0)))
      return { kind: 'out', i };
  }
  for (let j = 0; j < CIN; j++) {
    const c = new THREE.Vector3(-1.0, 0, -j * DZ);
    if (quadHit(ndc, c, new THREE.Vector3(M * CELL / 2, 0, 0), new THREE.Vector3(0, M * CELL / 2, 0)))
      return { kind: 'in' };
  }
  return null;
}

canvas.addEventListener('pointermove', (ev) => {
  const h = pick(ev);
  if (h) {
    canvas.style.cursor = 'pointer';
    const txt = h.kind === 'filter' ? `Filter #${h.i + 1}: ${CIN}×${state.K}×${state.K} — click to isolate`
      : h.kind === 'out' ? `Output channel #${h.i + 1} — produced by filter #${h.i + 1}`
        : `x_in: ${CIN}×${M}×${M} input volume`;
    showTooltip(txt, ev);
  } else {
    canvas.style.cursor = 'grab';
    hideTooltip();
  }
});

canvas.addEventListener('click', (ev) => {
  const h = pick(ev);
  if (!h) { state.sel = -1; applySelection(); hidePopup(); return; }
  if (h.kind === 'in') {
    showPopup('x_in — the input volume',
      `The input is C_in × M × M = ${CIN} × ${M} × ${M}. Every filter must have exactly C_in sheets so it can cover the whole depth of this volume in one placement.`);
    return;
  }
  state.sel = (state.sel === h.i) ? -1 : h.i;
  applySelection();
  if (state.sel >= 0) {
    const N = M - state.K + 1;
    showPopup(`Filter #${state.sel + 1} → output channel #${state.sel + 1}`,
      `This blue stack has C_in = ${CIN} sheets of ${state.K}×${state.K}, matching the input depth. Sliding it over x_in produces exactly ONE pink output plane of N×N = ${N}×${N}. The number of filters, C_out = ${state.cOut}, is therefore the depth of x_out.`);
  } else hidePopup();
});

/* ── guided steps ────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Two filters, 3×3', narration: "Two blue filter stacks, each three sheets deep to match the input's C_in = 3, convolve an 8×8×3 pink input to give a 6×6×2 output.", state: { cOut: 2, K: 3 } },
  { title: 'Add filters', narration: 'Raising C_out to 4 adds two more blue stacks on the left and two more pink sheets on the right — the output depth tracks the filter count exactly.', state: { cOut: 4, K: 3 } },
  { title: 'Grow the kernel', narration: 'Enlarging K to 5 widens each blue grid and the highlighted patch on x_in; M is unchanged but the output shrinks to N = 8 − 5 + 1 = 4.', state: { cOut: 4, K: 5 } },
  { title: 'Back to K = 3 and sweep', narration: 'With K = 3 again, watch the window sweep over the input: each stop fills one output cell, tracing out the full N×N plane for every filter.', state: { cOut: 2, K: 3 } }
];
let stepIdx = 0, tweenTimer = null;

function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const st = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = `${stepIdx + 1}. ${st.title}`;
  document.getElementById('stepNarr').textContent = st.narration;
  stopSweep();
  clearInterval(tweenTimer);
  tweenTimer = setInterval(() => {
    let changed = false;
    if (state.cOut !== st.state.cOut) { state.cOut += Math.sign(st.state.cOut - state.cOut); changed = true; }
    else if (state.K !== st.state.K) { state.K += Math.sign(st.state.K - state.K); changed = true; }
    if (changed) { syncInputs(); build(); }
    else { clearInterval(tweenTimer); if (stepIdx === 3) startSweep(); }
  }, 200);
}
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── go ──────────────────────────────────────────────────────────────────── */
syncInputs();
build();
document.getElementById('stepTitle').textContent = `1. ${STEPS[0].title}`;
document.getElementById('stepNarr').textContent = STEPS[0].narration;
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

