<div style="font-size:10px;color:#666;line-height:1.35;border-top:1px solid #dcdfe3;padding-top:4px;">
  Click a blue filter stack (or its pink output sheet) to isolate it. Drag the figure to ease the
  oblique shear out and see the true 3D stacks; “Figure view” restores the printed pose.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── element spec (one line per drawn element) ──────────────────────────────
// blue filter sheet  → PlaneGeometry(K*0.50, K*0.50) fill #cfe4f3 + thick quad-strip grid #111
// filter stack       → C_in = 3 sheets at z = 0, -0.62, -1.24 (front sheet z = 0, recedes up-left)
// pink input sheet   → PlaneGeometry(8*0.42, 8*0.42) fill #f7dcdc + quad-strip grid, 3 sheets
// pink output sheet  → PlaneGeometry(N*0.42, N*0.42) fill #f7dcdc + grid, C_out sheets
// braces             → Line, two-quarter-arc curly brace, black
// receptive patch    → blue quad + grid on front input sheet, red frame on all 3 sheets (fades in)
// output cell marker → red frame quad on each output sheet (fades in)
// accumulated cells  → InstancedMesh(PlaneGeometry) #d94f4f @40% (fades in)
// w / x_in / x_out / ⋆ / = / C_in / C_out / K / M / N → addLabel HTML (serif)
──────────────────────────────────────────────────────────────────────────── */

const CELL  = 0.42;          // pink (input / output) cell
const CELLF = 0.50;          // blue (filter) cell — slightly larger, as printed
const DZ    = 0.62;          // world depth per sheet  → ~0.22 screen units under cabinet shear
const CIN   = 3;
const M     = 8;
const BLUE = 0xcfe4f3, PINK = 0xf7dcdc, RED = 0xd94f4f, BLACK = 0x111111;
const LW = 0.021, BLW = 0.036;                 // grid line / outer border thickness
const OBL_ANGLE = 135;                          // depth recedes UP-LEFT (matches printed pose)
const SHEAR = 0.5 * Math.cos(Math.PI / 4);      // depthScale * cos45 → screen units per world z

const AX = () => new THREE.Vector3(1, 0, 0);
const AY = () => new THREE.Vector3(0, 1, 0);
const AZ = () => new THREE.Vector3(0, 0, 1);

const root = new THREE.Group();
scene.add(root);

const state = { cOut: 2, K: 3, sel: -1, sweeping: false, idx: 0, filled: [], hi: false };

let filterStacks = [], outSheets = [], patchNodes = [], outMarkers = [], hiMats = [];
let inputStack = null, firstBuild = true;
let hiAlpha = 0, hiTarget = 0;

/* ── labels ──────────────────────────────────────────────────────────────── */
const myLabels = [];
const SER = s => `<span style="font-family:'Times New Roman',Times,serif">${s}</span>`;
function L(text, pos, opts) { const e = addLabel(text, pos, opts); myLabels.push(e); return e; }
function clearLabels() {
  while (myLabels.length) {
    const e = myLabels.pop();
    const i = _labels.indexOf(e);
    if (i >= 0) _labels.splice(i, 1);
    e.div.remove();
  }
}

/* ── geometry helpers ────────────────────────────────────────────────────── */
function pushQuad(arr, x0, y0, x1, y1) {
  arr.push(x0, y0, 0, x1, y0, 0, x1, y1, 0, x0, y0, 0, x1, y1, 0, x0, y1, 0);
}

/** heavy grid: every cell border is a thin quad, outer border thicker */
function gridGeom(rows, cols, cell) {
  const w = cols * cell, h = rows * cell, p = [];
  for (let i = 0; i <= cols; i++) {
    const x = -w / 2 + i * cell, t = (i === 0 || i === cols) ? BLW : LW;
    pushQuad(p, x - t / 2, -h / 2 - BLW / 2, x + t / 2, h / 2 + BLW / 2);
  }
  for (let j = 0; j <= rows; j++) {
    const y = -h / 2 + j * cell, t = (j === 0 || j === rows) ? BLW : LW;
    pushQuad(p, -w / 2 - BLW / 2, y - t / 2, w / 2 + BLW / 2, y + t / 2);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  return g;
}

function frameGeom(w, h, t) {
  const p = [], a = w / 2, b = h / 2;
  pushQuad(p, -a - t / 2, b - t / 2, a + t / 2, b + t / 2);
  pushQuad(p, -a - t / 2, -b - t / 2, a + t / 2, -b + t / 2);
  pushQuad(p, -a - t / 2, -b, -a + t / 2, b);
  pushQuad(p, a - t / 2, -b, a + t / 2, b);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  return g;
}

function makeSheetFactory(rows, cols, cell, color) {
  const fillG = new THREE.PlaneGeometry(cols * cell, rows * cell);
  const gridG = gridGeom(rows, cols, cell);
  return () => {
    const g = new THREE.Group();
    g.add(new THREE.Mesh(fillG, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide })));
    const gl = new THREE.Mesh(gridG, new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.DoubleSide }));
    gl.position.z = 0.006;
    g.add(gl);
    return g;
  };
}

function makeStack(rows, cols, cell, color, n) {
  const mk = makeSheetFactory(rows, cols, cell, color);
  const g = new THREE.Group();
  for (let i = 0; i < n; i++) { const s = mk(); s.position.z = -i * DZ; g.add(s); }
  return g;
}

/* ── curly braces ────────────────────────────────────────────────────────── */
function bracePoints(Lz, r) {
  r = Math.min(r, Lz / 4);
  const p = [], N = 10;
  for (let k = 0; k <= N; k++) { const t = Math.PI - (Math.PI / 2) * (k / N); p.push([-Lz / 2 + r + r * Math.cos(t), r * Math.sin(t)]); }
  for (let k = 0; k <= N; k++) { const t = -Math.PI / 2 + (Math.PI / 2) * (k / N); p.push([-r + r * Math.cos(t), 2 * r + r * Math.sin(t)]); }
  const q = p.slice();
  for (let k = p.length - 2; k >= 0; k--) q.push([-p[k][0], p[k][1]]);
  return q;
}

/** draws a curly brace; returns the world position of its middle tip */
function addBrace(center, axis, bulge, len, r = 0.13) {
  const a = axis.normalize(), b = bulge.normalize();
  const Lz = Math.max(len, 0.3);
  const pts = bracePoints(Lz, r).map(([u, v]) =>
    center.clone().addScaledVector(a, u).addScaledVector(b, v));
  root.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: BLACK })));
  return center.clone().addScaledVector(b, 2 * Math.min(r, Lz / 4));
}

function setOpacity(obj, o) {
  obj.traverse(n => {
    if (n.userData && n.userData.skipOpacity) return;
    if (n.material) { n.material.transparent = true; n.material.opacity = o; }
  });
}

/* ── highlight fade bookkeeping ──────────────────────────────────────────── */
function regHi(mesh, mat, base, idx) {
  mesh.userData.skipOpacity = true;
  hiMats.push({ mat, base, idx });
}
function applyHi() {
  for (const e of hiMats) {
    const sel = e.idx < 0 ? 1 : ((state.sel < 0 || state.sel === e.idx) ? 1 : 0.3);
    e.mat.transparent = true;
    e.mat.opacity = e.base * hiAlpha * sel;
    e.mat.visible = e.mat.opacity > 0.012;
  }
}
(function tickHi() {
  requestAnimationFrame(tickHi);
  if (Math.abs(hiAlpha - hiTarget) > 0.004) { hiAlpha += (hiTarget - hiAlpha) * 0.16; applyHi(); }
  else if (hiAlpha !== hiTarget) { hiAlpha = hiTarget; applyHi(); }
})();
function refreshHiTarget() { hiTarget = (state.hi || state.sweeping) ? 1 : 0; }

/* ── build ───────────────────────────────────────────────────────────────── */
function clearRoot() { while (root.children.length) { const c = root.children.pop(); _disposeObject(c); } }

function build() {
  clearRoot(); clearLabels();
  filterStacks = []; outSheets = []; patchNodes = []; outMarkers = []; hiMats = [];

  const K = state.K, C = state.cOut, N = M - K + 1;
  const fHalf = K * CELLF / 2, inHalf = M * CELL / 2, outHalf = N * CELL / 2;
  const fx = -6.2, inX = -1.0, outX = 4.6;
  const pitch = K * CELLF + 0.85;
  const stackY = i => ((C - 1) / 2 - i) * pitch;
  const zMid = -(CIN - 1) * DZ / 2;
  const dOff = SHEAR * (CIN - 1) * DZ;          // how far the back sheet climbs on screen
  const dOffOut = SHEAR * (C - 1) * DZ;

  /* filters */
  for (let i = 0; i < C; i++) {
    const st = makeStack(K, K, CELLF, BLUE, CIN);
    st.position.set(fx, stackY(i), 0);
    root.add(st);
    filterStacks.push(st);
  }

  /* input */
  inputStack = makeStack(M, M, CELL, PINK, CIN);
  inputStack.position.set(inX, 0, 0);
  root.add(inputStack);

  /* receptive patch on every input sheet (hidden until the sweep or the checkbox) */
  const patchFrameG = frameGeom(K * CELL, K * CELL, 0.032);
  const patchGridG = gridGeom(K, K, CELL);
  for (let j = 0; j < CIN; j++) {
    const g = new THREE.Group();
    if (j === 0) {
      const mF = new THREE.MeshBasicMaterial({ color: BLUE, side: THREE.DoubleSide, transparent: true });
      const m = new THREE.Mesh(new THREE.PlaneGeometry(K * CELL, K * CELL), mF);
      m.position.z = 0.012; g.add(m); regHi(m, mF, 0.95, -1);
      const mG = new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.DoubleSide, transparent: true });
      const gl = new THREE.Mesh(patchGridG, mG); gl.position.z = 0.016; g.add(gl); regHi(gl, mG, 1, -1);
    }
    const mR = new THREE.MeshBasicMaterial({ color: RED, side: THREE.DoubleSide, transparent: true });
    const fr = new THREE.Mesh(patchFrameG, mR); fr.position.z = 0.02; g.add(fr); regHi(fr, mR, 1, -1);
    g.position.z = -j * DZ;
    inputStack.add(g);
    patchNodes.push(g);
  }

  /* output: one sheet per filter */
  const outGroup = new THREE.Group();
  outGroup.position.set(outX, 0, 0);
  root.add(outGroup);
  const cellFrameG = frameGeom(CELL, CELL, 0.032);
  const mkOut = makeSheetFactory(N, N, CELL, PINK);
  for (let i = 0; i < C; i++) {
    const s = mkOut();
    s.position.z = -i * DZ;

    const instM = new THREE.MeshBasicMaterial({ color: RED, transparent: true, side: THREE.DoubleSide });
    const inst = new THREE.InstancedMesh(new THREE.PlaneGeometry(CELL * 0.94, CELL * 0.94), instM, Math.max(1, N * N));
    inst.frustumCulled = false;
    s.add(inst); regHi(inst, instM, 0.4, i);

    const mkM = new THREE.MeshBasicMaterial({ color: RED, transparent: true, side: THREE.DoubleSide });
    const mk = new THREE.Mesh(cellFrameG, mkM);
    mk.position.z = 0.02;
    s.add(mk); regHi(mk, mkM, 1, i);
    outMarkers.push(mk);

    outGroup.add(s);
    outSheets.push({ group: s, inst });
  }

  /* ── braces ── */
  const topY = stackY(0) + fHalf, botY = stackY(C - 1) - fHalf;

  // tall C_out filters brace (clears the back sheets, which now lean LEFT)
  let tip = addBrace(new THREE.Vector3(fx - fHalf - dOff - 0.50, (topY + dOff + botY) / 2, 0),
    AY(), AX().negate(), (topY + dOff) - botY, 0.17);
  L(SER(`<span style="display:inline-block;transform:rotate(-90deg)"><i>C</i><sub>out</sub> filters</span>`),
    tip.clone().add(new THREE.Vector3(-0.50, 0, 0)), { fontSize: '15px' });

  // C_in above the top filter stack, following the depth direction
  tip = addBrace(new THREE.Vector3(fx + fHalf * 0.45, topY + 0.34, zMid), AZ(), AY(), (CIN - 1) * DZ, 0.12);
  L(SER('<i>C</i><sub>in</sub>'), tip.clone().add(new THREE.Vector3(0.42, 0.22, 0)), { fontSize: '16px' });

  // K on the right of the lowest filter stack
  tip = addBrace(new THREE.Vector3(fx + fHalf + 0.28, stackY(C - 1), 0), AY(), AX(), K * CELLF, 0.13);
  L(SER('<i>K</i>'), tip.clone().add(new THREE.Vector3(0.36, 0, 0)), { fontSize: '16px' });

  // K under the lowest filter stack
  tip = addBrace(new THREE.Vector3(fx, stackY(C - 1) - fHalf - 0.28, 0), AX(), AY().negate(), K * CELLF, 0.13);
  L(SER('<i>K</i>'), tip.clone().add(new THREE.Vector3(0, -0.36, 0)), { fontSize: '16px' });

  // C_in above the input
  tip = addBrace(new THREE.Vector3(inX + inHalf * 0.45, inHalf + 0.34, zMid), AZ(), AY(), (CIN - 1) * DZ, 0.12);
  L(SER('<i>C</i><sub>in</sub>'), tip.clone().add(new THREE.Vector3(0.42, 0.22, 0)), { fontSize: '16px' });

  // M under the input
  tip = addBrace(new THREE.Vector3(inX, -inHalf - 0.28, 0), AX(), AY().negate(), M * CELL, 0.15);
  L(SER('<i>M</i>'), tip.clone().add(new THREE.Vector3(0, -0.38, 0)), { fontSize: '16px' });

  // C_out above the output
  tip = addBrace(new THREE.Vector3(outX + outHalf * 0.45, outHalf + 0.34, -(C - 1) * DZ / 2),
    AZ(), AY(), Math.max((C - 1) * DZ, 0.42), 0.12);
  L(SER('<i>C</i><sub>out</sub>'), tip.clone().add(new THREE.Vector3(0.44, 0.22, 0)), { fontSize: '16px' });

  // N on the right of the output
  tip = addBrace(new THREE.Vector3(outX + outHalf + 0.30, 0, 0), AY(), AX(), N * CELL, 0.15);
  L(SER('<i>N</i>'), tip.clone().add(new THREE.Vector3(0.38, 0, 0)), { fontSize: '16px' });

  /* ── camera (oblique: depth recedes up-left, front sheet lower-right) ── */
  if (firstBuild || !_userMovedCamera) {
    setCameraView({ projection: 'oblique', obliqueAngleDeg: OBL_ANGLE, depthScale: 0.5, heightFraction: 0.62 });
  }
  firstBuild = false;

  /* ── headline labels & operators (generous clearance above each stack) ── */
  L(SER('<b>w</b>'), new THREE.Vector3(fx - 0.15, topY + dOff + 0.88, 0), { fontSize: '18px' });
  L(SER('<b>x</b><sub>in</sub>'), new THREE.Vector3(inX, inHalf + dOff + 0.88, 0), { fontSize: '18px' });
  L(SER('<b>x</b><sub>out</sub>'), new THREE.Vector3(outX, outHalf + dOffOut + 0.88, 0), { fontSize: '18px' });
  L(SER('&#8902;'), new THREE.Vector3(-3.85, 0, 0), { fontSize: '26px' });
  L(SER('='), new THREE.Vector3(2.0, 0, 0), { fontSize: '26px' });

  /* ── state-dependent visuals ── */
  state.filled = new Array(N * N).fill(false);
  state.idx = 0;
  if (state.sel >= C) state.sel = -1;
  updatePatch(0, 0);
  updateFilled();
  applySelection();
  applyHi();
  updateReadout();
}

/* ── highlight / accumulation ────────────────────────────────────────────── */
function updatePatch(row, col) {
  const K = state.K, N = M - K + 1;
  const px = -M * CELL / 2 + (col + K / 2) * CELL;
  const py = M * CELL / 2 - (row + K / 2) * CELL;
  patchNodes.forEach(g => { g.position.x = px; g.position.y = py; });
  const ox = -N * CELL / 2 + (col + 0.5) * CELL;
  const oy = N * CELL / 2 - (row + 0.5) * CELL;
  outMarkers.forEach(g => { g.position.x = ox; g.position.y = oy; });
}

const _mtx = new THREE.Matrix4();
function updateFilled() {
  const N = M - state.K + 1;
  for (const o of outSheets) {
    for (let p = 0; p < N * N; p++) {
      const r = Math.floor(p / N), c = p % N;
      const s = state.filled[p] ? 1 : 0.0001;
      _mtx.makeScale(s, s, 1);
      _mtx.setPosition(-N * CELL / 2 + (c + 0.5) * CELL, N * CELL / 2 - (r + 0.5) * CELL, 0.01);
      o.inst.setMatrixAt(p, _mtx);
    }
    o.inst.instanceMatrix.needsUpdate = true;
  }
}

function applySelection() {
  for (let i = 0; i < filterStacks.length; i++)
    setOpacity(filterStacks[i], (state.sel < 0 || state.sel === i) ? 1 : 0.3);
  for (let i = 0; i < outSheets.length; i++)
    setOpacity(outSheets[i].group, (state.sel < 0 || state.sel === i) ? 1 : 0.3);
  const b = document.getElementById('selectFilter');
  b.textContent = 'Isolate filter: ' + (state.sel < 0 ? 'none' : '#' + (state.sel + 1));
  b.classList.toggle('active', state.sel >= 0);
  applyHi();
}

function updateReadout() {
  const K = state.K, C = state.cOut, N = M - K + 1;
  document.getElementById('shapeOut').innerHTML =
    `w    : ${C} × ${CIN} × ${K} × ${K}<br>` +
    `x_in : ${CIN} × ${M} × ${M}<br>` +
    `x_out: ${C} × ${N} × ${N}&nbsp;&nbsp;(N = M−K+1)`;
}

/* ── sweep animation ─────────────────────────────────────────────────────── */
let sweepTimer = null;
function sweepTick() {
  const N = M - state.K + 1;
  if (state.idx === 0) state.filled.fill(false);
  const p = state.idx, r = Math.floor(p / N), c = p % N;
  updatePatch(r, c);
  state.filled[p] = true;
  updateFilled();
  state.idx = (p + 1) % (N * N);
}
function startSweep() {
  if (state.sweeping) return;
  state.sweeping = true; refreshHiTarget();
  const b = document.getElementById('sweepWindow');
  b.classList.add('active'); b.innerHTML = '❚❚ Pause sweep';
  sweepTick();
  sweepTimer = setInterval(sweepTick, 250);
}
function stopSweep() {
  state.sweeping = false; refreshHiTarget();
  clearInterval(sweepTimer); sweepTimer = null;
  const b = document.getElementById('sweepWindow');
  b.classList.remove('active'); b.innerHTML = '▶ Slide the filter across x<sub>in</sub>';
}

/* ── controls ────────────────────────────────────────────────────────────── */
const cOutInput = document.getElementById('cOutFilters');
const kInput = document.getElementById('kernelSize');
const hiInput = document.getElementById('showPatch');

function syncInputs() {
  cOutInput.value = state.cOut; kInput.value = state.K;
  document.getElementById('cOutVal').textContent = state.cOut;
  document.getElementById('kVal').textContent = state.K;
  hiInput.checked = state.hi;
}

cOutInput.addEventListener('input', () => { state.cOut = +cOutInput.value; syncInputs(); build(); });
kInput.addEventListener('input', () => { state.K = +kInput.value; syncInputs(); build(); });
hiInput.addEventListener('change', () => { state.hi = hiInput.checked; refreshHiTarget(); });
document.getElementById('sweepWindow').addEventListener('click', () => {
  if (state.sweeping) { stopSweep(); state.idx = 0; state.filled.fill(false); updateFilled(); updatePatch(0, 0); }
  else startSweep();
});
document.getElementById('selectFilter').addEventListener('click', () => {
  state.sel = state.sel + 1 >= state.cOut ? -1 : state.sel + 1;
  applySelection();
});

/* ── screen-space picking (the oblique shear makes raycasting unreliable) ── */
function quadHit(ndc, center, ex, ey) {
  const c = center.clone().project(camera);
  const a = center.clone().add(ex).project(camera).sub(c);
  const b = center.clone().add(ey).project(camera).sub(c);
  const dx = ndc.x - c.x, dy = ndc.y - c.y;
  const det = a.x * b.y - a.y * b.x;
  if (Math.abs(det) < 1e-9) return false;
  const s = (dx * b.y - dy * b.x) / det, t = (a.x * dy - a.y * dx) / det;
  return Math.abs(s) <= 1 && Math.abs(t) <= 1;
}

function pick(ev) {
  const rect = canvas.getBoundingClientRect();
  const ndc = {
    x: ((ev.clientX - rect.left) / rect.width) * 2 - 1,
    y: -((ev.clientY - rect.top) / rect.height) * 2 + 1
  };
  const K = state.K, N = M - K + 1;
  for (let i = 0; i < filterStacks.length; i++) {
    const st = filterStacks[i];
    for (let j = 0; j < CIN; j++) {
      const c = new THREE.Vector3(st.position.x, st.position.y, -j * DZ);
      if (quadHit(ndc, c, new THREE.Vector3(K * CELLF / 2, 0, 0), new THREE.Vector3(0, K * CELLF / 2, 0)))
        return { kind: 'filter', i };
    }
  }
  for (let i = 0; i < outSheets.length; i++) {
    const c = new THREE.Vector3(4.6, 0, -i * DZ);
    if (quadHit(ndc, c, new THREE.Vector3(N * CELL / 2, 0, 0), new THREE.Vector3(0, N * CELL / 2, 0)))
      return { kind: 'out', i };
  }
  for (let j = 0; j < CIN; j++) {
    const c = new THREE.Vector3(-1.0, 0, -j * DZ);
    if (quadHit(ndc, c, new THREE.Vector3(M * CELL / 2, 0, 0), new THREE.Vector3(0, M * CELL / 2, 0)))
      return { kind: 'in' };
  }
  return null;
}

canvas.addEventListener('pointermove', (ev) => {
  const h = pick(ev);
  if (h) {
    canvas.style.cursor = 'pointer';
    const txt = h.kind === 'filter' ? `Filter #${h.i + 1}: ${CIN}×${state.K}×${state.K} — click to isolate`
      : h.kind === 'out' ? `Output channel #${h.i + 1} — produced by filter #${h.i + 1}`
        : `x_in: ${CIN}×${M}×${M} input volume`;
    showTooltip(txt, ev);
  } else { canvas.style.cursor = 'grab'; hideTooltip(); }
});

canvas.addEventListener('click', (ev) => {
  const h = pick(ev);
  if (!h) { state.sel = -1; applySelection(); hidePopup(); return; }
  if (h.kind === 'in') {
    showPopup('x_in — the input volume',
      `The input is C_in × M × M = ${CIN} × ${M} × ${M}. Every filter must have exactly C_in sheets so it covers the full depth of this volume in one placement.`);
    return;
  }
  state.sel = (state.sel === h.i) ? -1 : h.i;
  applySelection();
  if (state.sel >= 0) {
    const N = M - state.K + 1;
    showPopup(`Filter #${state.sel + 1} → output channel #${state.sel + 1}`,
      `This blue stack has C_in = ${CIN} sheets of ${state.K}×${state.K}, matching the input depth. Sliding it over x_in produces exactly ONE pink output plane of N×N = ${N}×${N}. The number of filters, C_out = ${state.cOut}, is therefore the depth of x_out.`);
  } else hidePopup();
});

/* ── guided steps ────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Two filters, 3×3', narration: "Two blue filter stacks, each three sheets deep to match the input's C_in = 3, convolve an 8×8×3 pink input to give a 6×6×2 output.", state: { cOut: 2, K: 3 } },
