// @FIGURE_CODE_BEGIN
/* ── element spec (one line per drawn element) ──────────────────────────────
// blue filter sheet  → PlaneGeometry(K*0.50, K*0.50) fill #cfe4f3 + thick quad-strip grid #111
// filter stack       → C_in = 3 sheets at z = 0, -0.62, -1.24 (front sheet z = 0, recedes up-left)
// pink input sheet   → PlaneGeometry(8*0.42, 8*0.42) fill #f7dcdc + quad-strip grid, 3 sheets
// pink output sheet  → PlaneGeometry(N*0.42, N*0.42) fill #f7dcdc + grid, C_out sheets
// braces             → Line, two-quarter-arc curly brace, black
// receptive patch    → blue quad + grid on front input sheet, red frame on all 3 sheets (fades in)
// output cell marker → red frame quad on each output sheet (fades in)
// accumulated cells  → InstancedMesh(PlaneGeometry) #d94f4f @40% (fades in)
// w / x_in / x_out / ⋆ / = / C_in / C_out / K / M / N → addLabel HTML (serif)
──────────────────────────────────────────────────────────────────────────── */

const CELL  = 0.42;          // pink (input / output) cell
const CELLF = 0.50;          // blue (filter) cell — slightly larger, as printed
const DZ    = 0.62;          // world depth per sheet  → ~0.22 screen units under cabinet shear
const CIN   = 3;
const M     = 8;
const BLUE = 0xcfe4f3, PINK = 0xf7dcdc, RED = 0xd94f4f, BLACK = 0x111111;
const LW = 0.021, BLW = 0.036;                 // grid line / outer border thickness
const OBL_ANGLE = 135;                          // depth recedes UP-LEFT (matches printed pose)
const SHEAR = 0.5 * Math.cos(Math.PI / 4);      // depthScale * cos45 → screen units per world z

const AX = () => new THREE.Vector3(1, 0, 0);
const AY = () => new THREE.Vector3(0, 1, 0);
const AZ = () => new THREE.Vector3(0, 0, 1);

const root = new THREE.Group();
scene.add(root);

const state = { cOut: 2, K: 3, sel: -1, sweeping: false, idx: 0, filled: [], hi: false };

let filterStacks = [], outSheets = [], patchNodes = [], outMarkers = [], hiMats = [];
let inputStack = null, firstBuild = true;
let hiAlpha = 0, hiTarget = 0;

/* ── labels ──────────────────────────────────────────────────────────────── */
const myLabels = [];
const SER = s => `<span style="font-family:'Times New Roman',Times,serif">${s}</span>`;
