/* ── geometry helpers ────────────────────────────────────────────────────── */
function pushQuad(arr, x0, y0, x1, y1) {
  arr.push(x0, y0, 0, x1, y0, 0, x1, y1, 0, x0, y0, 0, x1, y1, 0, x0, y1, 0);
}

/** heavy grid: every cell border is a thin quad, outer border thicker */
function gridGeom(rows, cols, cell) {
  const w = cols * cell, h = rows * cell, p = [];
  for (let i = 0; i <= cols; i++) {
    const x = -w / 2 + i * cell, t = (i === 0 || i === cols) ? BLW : LW;
    pushQuad(p, x - t / 2, -h / 2 - BLW / 2, x + t / 2, h / 2 + BLW / 2);
  }
  for (let j = 0; j <= rows; j++) {
    const y = -h / 2 + j * cell, t = (j === 0 || j === rows) ? BLW : LW;
    pushQuad(p, -w / 2 - BLW / 2, y - t / 2, w / 2 + BLW / 2, y + t / 2);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  return g;
}

function frameGeom(w, h, t) {
  const p = [], a = w / 2, b = h / 2;
  pushQuad(p, -a - t / 2, b - t / 2, a + t / 2, b + t / 2);
  pushQuad(p, -a - t / 2, -b - t / 2, a + t / 2, -b + t / 2);
  pushQuad(p, -a - t / 2, -b, -a + t / 2, b);
  pushQuad(p, a - t / 2, -b, a + t / 2, b);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  return g;
}

function makeSheetFactory(rows, cols, cell, color) {
  const fillG = new THREE.PlaneGeometry(cols * cell, rows * cell);
  const gridG = gridGeom(rows, cols, cell);
  return () => {
    const g = new THREE.Group();
    g.add(new THREE.Mesh(fillG, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide })));
    const gl = new THREE.Mesh(gridG, new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.DoubleSide }));
    gl.position.z = 0.006;
    g.add(gl);
    return g;
