  const Lz = Math.max(len, 0.3);
  const pts = bracePoints(Lz, r).map(([u, v]) =>
    center.clone().addScaledVector(a, u).addScaledVector(b, v));
  root.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: BLACK })));
  return center.clone().addScaledVector(b, 2 * Math.min(r, Lz / 4));
}

function setOpacity(obj, o) {
