  L(SER('<i>C</i><sub>in</sub>'), tip.clone().add(new THREE.Vector3(0.42, 0.22, 0)), { fontSize: '16px' });

  // K on the right of the lowest filter stack
  tip = addBrace(new THREE.Vector3(fx + fHalf + 0.28, stackY(C - 1), 0), AY(), AX(), K * CELLF, 0.13);
  L(SER('<i>K</i>'), tip.clone().add(new THREE.Vector3(0.36, 0, 0)), { fontSize: '16px' });

  // K under the lowest filter stack
  tip = addBrace(new THREE.Vector3(fx, stackY(C - 1) - fHalf - 0.28, 0), AX(), AY().negate(), K * CELLF, 0.13);
  L(SER('<i>K</i>'), tip.clone().add(new THREE.Vector3(0, -0.36, 0)), { fontSize: '16px' });

  // C_in above the input
  tip = addBrace(new THREE.Vector3(inX + inHalf * 0.45, inHalf + 0.34, zMid), AZ(), AY(), (CIN - 1) * DZ, 0.12);
  L(SER('<i>C</i><sub>in</sub>'), tip.clone().add(new THREE.Vector3(0.42, 0.22, 0)), { fontSize: '16px' });

  // M under the input
  tip = addBrace(new THREE.Vector3(inX, -inHalf - 0.28, 0), AX(), AY().negate(), M * CELL, 0.15);
  L(SER('<i>M</i>'), tip.clone().add(new THREE.Vector3(0, -0.38, 0)), { fontSize: '16px' });

  // C_out above the output
  tip = addBrace(new THREE.Vector3(outX + outHalf * 0.45, outHalf + 0.34, -(C - 1) * DZ / 2),
    AZ(), AY(), Math.max((C - 1) * DZ, 0.42), 0.12);
  L(SER('<i>C</i><sub>out</sub>'), tip.clone().add(new THREE.Vector3(0.44, 0.22, 0)), { fontSize: '16px' });

  // N on the right of the output
  tip = addBrace(new THREE.Vector3(outX + outHalf + 0.30, 0, 0), AY(), AX(), N * CELL, 0.15);
  L(SER('<i>N</i>'), tip.clone().add(new THREE.Vector3(0.38, 0, 0)), { fontSize: '16px' });

  /* ── camera (oblique: depth recedes up-left, front sheet lower-right) ── */
  if (firstBuild || !_userMovedCamera) {
    setCameraView({ projection: 'oblique', obliqueAngleDeg: OBL_ANGLE, depthScale: 0.5, heightFraction: 0.62 });
  }
  firstBuild = false;

  /* ── headline labels & operators (generous clearance above each stack) ── */
  L(SER('<b>w</b>'), new THREE.Vector3(fx - 0.15, topY + dOff + 0.88, 0), { fontSize: '18px' });
  L(SER('<b>x</b><sub>in</sub>'), new THREE.Vector3(inX, inHalf + dOff + 0.88, 0), { fontSize: '18px' });
  L(SER('<b>x</b><sub>out</sub>'), new THREE.Vector3(outX, outHalf + dOffOut + 0.88, 0), { fontSize: '18px' });
  L(SER('&#8902;'), new THREE.Vector3(-3.85, 0, 0), { fontSize: '26px' });
  L(SER('='), new THREE.Vector3(2.0, 0, 0), { fontSize: '26px' });

  /* ── state-dependent visuals ── */
  state.filled = new Array(N * N).fill(false);
  state.idx = 0;
  if (state.sel >= C) state.sel = -1;
  updatePatch(0, 0);
  updateFilled();
  applySelection();
  applyHi();
  updateReadout();
}

/* ── highlight / accumulation ────────────────────────────────────────────── */
function updatePatch(row, col) {
  const K = state.K, N = M - K + 1;
  const px = -M * CELL / 2 + (col + K / 2) * CELL;
  const py = M * CELL / 2 - (row + K / 2) * CELL;
  patchNodes.forEach(g => { g.position.x = px; g.position.y = py; });
  const ox = -N * CELL / 2 + (col + 0.5) * CELL;
  const oy = N * CELL / 2 - (row + 0.5) * CELL;
  outMarkers.forEach(g => { g.position.x = ox; g.position.y = oy; });
}

const _mtx = new THREE.Matrix4();
function updateFilled() {
  const N = M - state.K + 1;
  for (const o of outSheets) {
    for (let p = 0; p < N * N; p++) {
      const r = Math.floor(p / N), c = p % N;
      const s = state.filled[p] ? 1 : 0.0001;
      _mtx.makeScale(s, s, 1);
      _mtx.setPosition(-N * CELL / 2 + (c + 0.5) * CELL, N * CELL / 2 - (r + 0.5) * CELL, 0.01);
      o.inst.setMatrixAt(p, _mtx);
    }
    o.inst.instanceMatrix.needsUpdate = true;
  }
}

function applySelection() {
  for (let i = 0; i < filterStacks.length; i++)
    setOpacity(filterStacks[i], (state.sel < 0 || state.sel === i) ? 1 : 0.3);
  for (let i = 0; i < outSheets.length; i++)
    setOpacity(outSheets[i].group, (state.sel < 0 || state.sel === i) ? 1 : 0.3);
  const b = document.getElementById('selectFilter');
  b.textContent = 'Isolate filter: ' + (state.sel < 0 ? 'none' : '#' + (state.sel + 1));
  b.classList.toggle('active', state.sel >= 0);
  applyHi();
}

function updateReadout() {
  const K = state.K, C = state.cOut, N = M - K + 1;
  document.getElementById('shapeOut').innerHTML =
    `w    : ${C} × ${CIN} × ${K} × ${K}<br>` +
    `x_in : ${CIN} × ${M} × ${M}<br>` +
    `x_out: ${C} × ${N} × ${N}&nbsp;&nbsp;(N = M−K+1)`;
}

/* ── sweep animation ─────────────────────────────────────────────────────── */
let sweepTimer = null;
function sweepTick() {
  const N = M - state.K + 1;
  if (state.idx === 0) state.filled.fill(false);
  const p = state.idx, r = Math.floor(p / N), c = p % N;
  updatePatch(r, c);
  state.filled[p] = true;
  updateFilled();
  state.idx = (p + 1) % (N * N);
}
function startSweep() {
  if (state.sweeping) return;
  state.sweeping = true; refreshHiTarget();
  const b = document.getElementById('sweepWindow');
  b.classList.add('active'); b.innerHTML = '❚❚ Pause sweep';
  sweepTick();
  sweepTimer = setInterval(sweepTick, 250);
}
function stopSweep() {
  state.sweeping = false; refreshHiTarget();
  clearInterval(sweepTimer); sweepTimer = null;
  const b = document.getElementById('sweepWindow');
  b.classList.remove('active'); b.innerHTML = '▶ Slide the filter across x<sub>in</sub>';
}

/* ── controls ────────────────────────────────────────────────────────────── */
const cOutInput = document.getElementById('cOutFilters');
const kInput = document.getElementById('kernelSize');
const hiInput = document.getElementById('showPatch');

function syncInputs() {
  cOutInput.value = state.cOut; kInput.value = state.K;
  document.getElementById('cOutVal').textContent = state.cOut;
  document.getElementById('kVal').textContent = state.K;
  hiInput.checked = state.hi;
}

cOutInput.addEventListener('input', () => { state.cOut = +cOutInput.value; syncInputs(); build(); });
kInput.addEventListener('input', () => { state.K = +kInput.value; syncInputs(); build(); });
hiInput.addEventListener('change', () => { state.hi = hiInput.checked; refreshHiTarget(); });
document.getElementById('sweepWindow').addEventListener('click', () => {
  if (state.sweeping) { stopSweep(); state.idx = 0; state.filled.fill(false); updateFilled(); updatePatch(0, 0); }
  else startSweep();
});
document.getElementById('selectFilter').addEventListener('click', () => {
  state.sel = state.sel + 1 >= state.cOut ? -1 : state.sel + 1;
  applySelection();
});

/* ── screen-space picking (the oblique shear makes raycasting unreliable) ── */
function quadHit(ndc, center, ex, ey) {
  const c = center.clone().project(camera);
  const a = center.clone().add(ex).project(camera).sub(c);
  const b = center.clone().add(ey).project(camera).sub(c);
  const dx = ndc.x - c.x, dy = ndc.y - c.y;
  const det = a.x * b.y - a.y * b.x;
  if (Math.abs(det) < 1e-9) return false;
  const s = (dx * b.y - dy * b.x) / det, t = (a.x * dy - a.y * dx) / det;
  return Math.abs(s) <= 1 && Math.abs(t) <= 1;
}

function pick(ev) {
  const rect = canvas.getBoundingClientRect();
  const ndc = {
    x: ((ev.clientX - rect.left) / rect.width) * 2 - 1,
    y: -((ev.clientY - rect.top) / rect.height) * 2 + 1
  };
  const K = state.K, N = M - K + 1;
  for (let i = 0; i < filterStacks.length; i++) {
    const st = filterStacks[i];
    for (let j = 0; j < CIN; j++) {
      const c = new THREE.Vector3(st.position.x, st.position.y, -j * DZ);
      if (quadHit(ndc, c, new THREE.Vector3(K * CELLF / 2, 0, 0), new THREE.Vector3(0, K * CELLF / 2, 0)))
        return { kind: 'filter', i };
    }
  }
  for (let i = 0; i < outSheets.length; i++) {
    const c = new THREE.Vector3(4.6, 0, -i * DZ);
    if (quadHit(ndc, c, new THREE.Vector3(N * CELL / 2, 0, 0), new THREE.Vector3(0, N * CELL / 2, 0)))
      return { kind: 'out', i };
  }
  for (let j = 0; j < CIN; j++) {
    const c = new THREE.Vector3(-1.0, 0, -j * DZ);
    if (quadHit(ndc, c, new THREE.Vector3(M * CELL / 2, 0, 0), new THREE.Vector3(0, M * CELL / 2, 0)))
      return { kind: 'in' };
  }
  return null;
}

canvas.addEventListener('pointermove', (ev) => {
  const h = pick(ev);
  if (h) {
    canvas.style.cursor = 'pointer';
    const txt = h.kind === 'filter' ? `Filter #${h.i + 1}: ${CIN}×${state.K}×${state.K} — click to isolate`
      : h.kind === 'out' ? `Output channel #${h.i + 1} — produced by filter #${h.i + 1}`
        : `x_in: ${CIN}×${M}×${M} input volume`;
    showTooltip(txt, ev);
  } else { canvas.style.cursor = 'grab'; hideTooltip(); }
});

canvas.addEventListener('click', (ev) => {
  const h = pick(ev);
  if (!h) { state.sel = -1; applySelection(); hidePopup(); return; }
  if (h.kind === 'in') {
    showPopup('x_in — the input volume',
      `The input is C_in × M × M = ${CIN} × ${M} × ${M}. Every filter must have exactly C_in sheets so it covers the full depth of this volume in one placement.`);
    return;
  }
  state.sel = (state.sel === h.i) ? -1 : h.i;
  applySelection();
  if (state.sel >= 0) {
    const N = M - state.K + 1;
    showPopup(`Filter #${state.sel + 1} → output channel #${state.sel + 1}`,
      `This blue stack has C_in = ${CIN} sheets of ${state.K}×${state.K}, matching the input depth. Sliding it over x_in produces exactly ONE pink output plane of N×N = ${N}×${N}. The number of filters, C_out = ${state.cOut}, is therefore the depth of x_out.`);
  } else hidePopup();
});

/* ── guided steps ────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Two filters, 3×3', narration: "Two blue filter stacks, each three sheets deep to match the input's C_in = 3, convolve an 8×8×3 pink input to give a 6×6×2 output.", state: { cOut: 2, K: 3 } },
  { title: 'Add filters', narration: 'Raising C_out to 4 adds two more blue stacks on the left and two more pink sheets on the right — the output depth tracks the filter count exactly.', state: { cOut: 4, K: 3 } },
  { title: 'Grow the kernel', narration: 'Enlarging K to 5 widens each blue grid and the highlighted patch on x_in; M is unchanged but the output shrinks to N = 8 − 5 + 1 = 4.', state: { cOut: 4, K: 5 } },
  { title: 'Back to K = 3 and sweep', narration: 'With K = 3 again, watch the window sweep over the input: each stop fills one output cell, tracing out the full N×N plane for every filter.', state: { cOut: 2, K: 3 } }
];
let stepIdx = 0, tweenTimer = null;

function goToStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const st = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = `${stepIdx + 1}. ${st.title}`;
  document.getElementById('stepNarr').textContent = st.narration;
  stopSweep();
  clearInterval(tweenTimer);
  tweenTimer = setInterval(() => {
    let changed = false;
    if (state.cOut !== st.state.cOut) { state.cOut += Math.sign(st.state.cOut - state.cOut); changed = true; }
    else if (state.K !== st.state.K) { state.K += Math.sign(st.state.K - state.K); changed = true; }
    if (changed) { syncInputs(); build(); }
    else { clearInterval(tweenTimer); if (stepIdx === 3) startSweep(); }
  }, 200);
}
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── go ──────────────────────────────────────────────────────────────────── */
syncInputs();
build();
refreshHiTarget();
document.getElementById('stepTitle').textContent = `1. ${STEPS[0].title}`;
document.getElementById('stepNarr').textContent = STEPS[0].narration;
// @FIGURE_CODE_END

